import {esc} from './weather-tools.js';
import {mapHailReports} from './hail-map.js';
export function createHailWatch(ctx){
 let places=[],owner='',ready=false,busy=false,epoch=0,error='',enabled=false,seen=new Set(),notice='';
 const currentUser=()=>ctx.get().me?.id||'';
 function resetUser(){const id=currentUser();if(id!==owner){owner=id;places=[];ready=false;busy=false;epoch++;error='';enabled=false;seen.clear();notice=''}}
 function summaries(){return places.map(p=>({...p,...mapHailReports(ctx.data(),p,{minutes:120,radius:p.radius})}))}
 function shell(){return `<section class="hail-watch" aria-label="Le tue zone grandine"><div class="hail-watch-heading"><div><h2>Le tue zone, a colpo d’occhio</h2><p>Fino a 5 zone salvate nel tuo account, anche sugli altri dispositivi.</p></div><button data-hail-watch-add>Salva questa zona</button></div><div id="hail-watch-places"></div><div class="hail-watch-heading"><button data-hail-watch-live aria-pressed="false">Avvisi in questa vista: spenti</button><p>Funzionano mentre questa mappa è aperta e visibile. Non sono notifiche a app chiusa.</p></div><p id="hail-watch-notice" role="status"></p></section>`}
 function paint(){resetUser();const host=document.querySelector('#hail-watch-places');if(!host)return;const rows=summaries();let html=!owner?'<p>Accedi per salvare e ritrovare le tue zone.</p>':busy&&!ready?'<p>Caricamento delle zone…</p>':error?`<p role="alert">${esc(error)}</p><button data-hail-watch-retry>Riprova</button>`:!places.length?'<p>Salva il comune di casa, del lavoro o di una persona cara. Le zone sono private.</p>':`<div class="hail-watch-grid">${rows.map(p=>{const closed=p.points.reduce((n,g)=>n+g.posts.filter(x=>x.ended).length,0);return `<article><button data-hail-watch-open="${p.slot}"><strong>${esc(p.name)}</strong><span>Entro ${p.radius} km</span><b>${p.fresh?`${p.shown} segnalazioni`:'Dati da aggiornare'}</b><small>${p.fresh?`${closed} con fine riferita dall’autore · altre non confermate come concluse`:'Nessuna conclusione sulla presenza di grandine'}</small></button><button data-hail-watch-edit="${p.slot}">Modifica</button><button data-hail-watch-remove="${p.slot}" aria-label="Rimuovi ${esc(p.name)} dalle tue zone">Rimuovi</button></article>`}).join('')}</div><p class="hail-watch-foot">Nessuna segnalazione non significa assenza di rischio. Le zone senza coordinate non entrano nei conteggi.${ctx.data()?.truncated?' Campione nazionale limitato a 500 segnalazioni.':''}</p>`;
 if(host.innerHTML!==html)host.innerHTML=html;
 const live=document.querySelector('[data-hail-watch-live]');if(live){live.setAttribute('aria-pressed',String(enabled));live.textContent='Avvisi in questa vista: '+(enabled?'accesi':'spenti')}
 const n=document.querySelector('#hail-watch-notice');if(n)n.textContent=notice;
 document.querySelector('[data-hail-watch-retry]')?.addEventListener('click',()=>load(true),{once:true});
 document.querySelectorAll('[data-hail-watch-open]').forEach(b=>b.onclick=()=>{const p=places.find(p=>p.slot===Number(b.dataset.hailWatchOpen));if(p){ctx.select({...p,source:'saved-area'});location.hash='grandine-mappa'}});
 document.querySelectorAll('[data-hail-watch-edit]').forEach(b=>b.onclick=()=>edit(places.find(p=>p.slot===Number(b.dataset.hailWatchEdit))));
 document.querySelectorAll('[data-hail-watch-remove]').forEach(b=>b.onclick=()=>{const p=places.find(p=>p.slot===Number(b.dataset.hailWatchRemove));if(!p)return;ctx.modal('Rimuovere questa zona?',`<p>${esc(p.name)} verrà rimossa dalle zone seguite del tuo account.</p>`,async()=>{await ctx.api('hail/watch',{slot:p.slot,remove:true});await load(true);return true})});
 }
 async function load(force=false){resetUser();if(!owner||busy||ready&&!force){paint();return}busy=true;error='';const token=++epoch,id=owner;paint();try{const d=await ctx.api('hail/watch');if(token!==epoch||id!==currentUser())return;if(!Array.isArray(d.places))throw Error('Dati delle zone non disponibili.');places=d.places;ready=true}catch(e){if(token===epoch)error=e.message}finally{if(token===epoch){busy=false;paint()}}}
 function edit(existing){resetUser();if(!owner)return ctx.login();if(!ready||busy){ctx.toast('Attendi il caricamento delle zone oppure premi Riprova.');return}const p=existing||ctx.get().place,slot=existing?.slot??[0,1,2,3,4].find(n=>!places.some(p=>p.slot===n));if(slot===undefined){ctx.toast('Hai già cinque zone: modifica o rimuovi una zona.');return}if(!Number.isFinite(p.latitude)||!Number.isFinite(p.longitude)||Math.abs(p.latitude)>85){ctx.toast('Cerca prima una località valida.');return}
 ctx.modal(existing?'Modifica zona':'Salva la zona selezionata',`<p>Centro: ${esc(p.name)}. Conserveremo una posizione arrotondata a circa un chilometro, visibile solo nel tuo account.</p><label class="field"><span>Comune selezionato</span><input id="hail-watch-name" readonly maxlength="80" value="${esc(p.name)}"></label><label class="field"><span>Raggio dal centro</span><select id="hail-watch-radius">${[2,5,10,25,50].map(n=>`<option value="${n}" ${n===(p.radius||25)?'selected':''}>${n} km</option>`).join('')}</select></label><p>I conteggi usano le zone dichiarate dei post; non individuano la posizione del temporale al metro.</p>`,async()=>{await ctx.api('hail/watch',{slot,name:document.querySelector('#hail-watch-name').value,latitude:p.latitude,longitude:p.longitude,radius:Number(document.querySelector('#hail-watch-radius').value),consent:true});await load(true);return true});
 }
 function update(){resetUser();if(enabled&&ready){const rows=summaries(),ids=new Set(rows.flatMap(p=>p.points.flatMap(g=>g.posts.filter(p=>!p.ended).map(p=>p.id))));const added=[...ids].filter(id=>!seen.has(id));if(added.length){notice=`${added.length} nuove segnalazioni nelle zone seguite. Apri la zona per leggere orari e testimonianze.`;ctx.toast(notice)}for(const id of ids)seen.add(id);if(seen.size>2000)seen=ids;}paint()}
 function bind(){resetUser();const a=document.querySelector('[data-hail-watch-add]'),b=document.querySelector('[data-hail-watch-live]');if(a)a.onclick=()=>edit();if(b)b.onclick=()=>{if(!owner)return ctx.login();if(!ready||!places.length){ctx.toast('Salva prima almeno una zona.');return}if(!enabled&&!mapHailReports(ctx.data(),ctx.get().place).fresh){ctx.toast('Aggiorna prima le segnalazioni per attivare gli avvisi.');return}enabled=!enabled;seen=new Set(summaries().flatMap(p=>p.points.flatMap(g=>g.posts.map(p=>p.id))));notice=enabled?'Avvisi attivi qui. Ricontrollo ogni 30 secondi; nessun avviso a app chiusa.':'Avvisi in questa vista spenti.';paint()};paint();load()}
 return {shell,bind,paint,update,invalidate(){resetUser();ready=false;load(true)}};
}
